/* WARNING: Script requires that SQLITE_DBCONFIG_DEFENSIVE be disabled */
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "recruitment_campaigns" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(255) NOT NULL, "slug" varchar(255) NOT NULL UNIQUE, "description" text NULL, "start_date" date NULL, "end_date" date NULL, "status" varchar(20) NOT NULL, "budget" decimal NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "company_id" bigint NOT NULL REFERENCES "companies" ("id") DEFERRABLE INITIALLY DEFERRED);
INSERT INTO recruitment_campaigns VALUES(1,'Tuyển dụng nhân sự Tech Quý 1/2026','tuyen-dung-tech-q1-2026','Chiến dịch tập trung tìm kiếm các vị trí Dev và Designer cho dự án JOBIO.','2026-01-01','2026-03-31','active',50000000,'2026-03-16 09:51:16.472010','2026-03-16 09:53:06.508542',1);
INSERT INTO recruitment_campaigns VALUES(2,'Thực tập sinh tiềm năng mùa hè','thuc-tap-sinh-he-2026','Chương trình thực tập sinh cho các bạn sinh viên năm cuối.','2026-05-01','2026-08-31','draft',10000000,'2026-03-16 09:51:16.475016','2026-03-16 09:53:06.510548',1);
INSERT INTO recruitment_campaigns VALUES(3,'tuyen thang 4','tuyen-thang-4-3rfm1','tuyen nhieu','2026-03-16','2026-03-22','draft',6,'2026-03-16 13:29:43.436982','2026-03-16 13:29:43.439009',1);
CREATE TABLE IF NOT EXISTS "recruitment_campaigns_jobs" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "campaign_id" bigint NOT NULL REFERENCES "recruitment_campaigns" ("id") DEFERRABLE INITIALLY DEFERRED, "job_id" bigint NOT NULL REFERENCES "jobs" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "recruitment_referrals_referralprogram_jobs" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "referralprogram_id" bigint NOT NULL REFERENCES "recruitment_referrals_referralprogram" ("id") DEFERRABLE INITIALLY DEFERRED, "job_id" bigint NOT NULL REFERENCES "jobs" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "recruitment_referrals_referral" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "candidate_name" varchar(255) NOT NULL, "candidate_email" varchar(254) NOT NULL, "candidate_phone" varchar(20) NOT NULL, "cv_file" varchar(500) NOT NULL, "referral_date" datetime NOT NULL, "notes" text NOT NULL, "job_id" bigint NOT NULL REFERENCES "jobs" ("id") DEFERRABLE INITIALLY DEFERRED, "referrer_id" bigint NOT NULL REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED, "program_id" bigint NOT NULL REFERENCES "recruitment_referrals_referralprogram" ("id") DEFERRABLE INITIALLY DEFERRED, "paid_at" datetime NULL, "status" varchar(20) NOT NULL);
CREATE TABLE IF NOT EXISTS "recruitment_referrals_referralprogram" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "title" varchar(255) NOT NULL, "description" text NOT NULL, "reward_amount" decimal NOT NULL, "currency" varchar(10) NOT NULL, "start_date" date NULL, "end_date" date NULL, "company_id" bigint NOT NULL REFERENCES "companies" ("id") DEFERRABLE INITIALLY DEFERRED, "reward_type" varchar(20) NOT NULL, "status" varchar(20) NOT NULL);
CREATE TABLE IF NOT EXISTS "referral_programs" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "program_name" varchar(255) NOT NULL, "description" text NULL, "bonus_amount" decimal NOT NULL, "bonus_currency" varchar(10) NOT NULL, "terms_conditions" text NULL, "is_active" bool NOT NULL, "start_date" date NULL, "end_date" date NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "company_id" bigint NOT NULL REFERENCES "companies" ("id") DEFERRABLE INITIALLY DEFERRED);
INSERT INTO referral_programs VALUES(1,'Thưởng giới thiệu Senior Frontend','Giới thiệu ứng viên cho vị trí Senior Frontend và nhận ngay phần thưởng khi ứng viên vượt qua thử việc.',5000000,'VND',NULL,1,'2026-03-01',NULL,'2026-03-16 14:49:24.193548','2026-03-16 14:49:24.193548',1);
INSERT INTO referral_programs VALUES(2,'Chương trình tuyển dụng Backend','Thưởng cho mỗi ứng viên Backend Engineer được giới thiệu và đi phỏng vấn.',2000000,'VND',NULL,1,'2026-03-05',NULL,'2026-03-16 14:49:24.201485','2026-03-16 14:49:24.201995',1);
INSERT INTO referral_programs VALUES(3,'Giới thiệu UI/UX Designer','Nhận thưởng khi giới thiệu thành công Designer cho dự án JOBIO.',3000000,'VND',NULL,1,'2026-03-10',NULL,'2026-03-16 14:49:24.211102','2026-03-16 14:49:24.211102',1);
CREATE TABLE IF NOT EXISTS "referrals" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "referred_email" varchar(255) NULL, "referred_name" varchar(255) NULL, "referred_phone" varchar(20) NULL, "status" varchar(20) NOT NULL, "bonus_amount" decimal NULL, "bonus_paid" bool NOT NULL, "bonus_paid_at" datetime NULL, "notes" text NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "job_id" bigint NOT NULL REFERENCES "jobs" ("id") DEFERRABLE INITIALLY DEFERRED, "program_id" bigint NULL REFERENCES "referral_programs" ("id") DEFERRABLE INITIALLY DEFERRED, "referred_recruiter_id" bigint NULL REFERENCES "recruiters" ("id") DEFERRABLE INITIALLY DEFERRED, "referrer_id" bigint NOT NULL REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED);
